+    if (n <= 32) { // Small N optimization: insertion sort
+        for (size_t i = 1; i < n; ++i) {
+            uint32_t key = a[i];
+            size_t j = i;
+            while (j > 0 && a[j - 1] > key) {
+                a[j] = a[j - 1];
+                j--;
+            }
+            a[j] = key;
+        }
+        return;
