+    for (int p = 0; p < NUM_PASSES; ++p) {
+        // Counting pass
+        uint32_t counts[256] = {0};
+        uint32_t shift = p * BITS_PER_PASS;
+
+        // Count frequencies
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (src[i] >> shift) & MASK;
+            counts[digit]++;
+        }
+
+        // Prefix sum calculation (cumulative counts)
+        uint32_t sum = 0;
+        for (int i = 0; i < 256; ++i) {
+            uint32_t count = counts[i];
+            counts[i] = sum;
+            sum += count;
+        }
+
+        // Placement pass (stable sort)
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (src[i] >> shift) & MASK;
+            size_t pos = counts[digit]++;
+            dst[pos] = src[i];
+        }
+
+        // Swap roles for next pass
